Translate("deDE", "undercity", {
	title = "Undercity",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Undercity liegt unter den Ruinen der {link:capital-city}Hauptstadt{/link} Lordaerons, im Osten von {link:tirisfal-glades}Tirisfal{/link}. Es ist die Hauptstadt der {link:forsaken}Verlassenen{/link} und der Sitz ihrer Königin, {link:sylvanas-windrunner}Sylvanas Windrunner{/link}. Seine Hallen wurden aus den Abwasserkanälen, Grüften und Katakomben der alten Stadt gehauen. Grüner Schleim fließt durch seine Kanäle, Fledermäuse kreisen unter seinen Gewölben, und seine vier großen Viertel umringen einen zentralen Hof, in dem die Verlassenen Handel treiben, Ränke schmieden und ihre Gifte brauen. Keine Stadt der Welt ist seltsamer, und nur wenige sind besser verteidigt.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Die ersten Tunnel wurden nicht von den Verlassenen gegraben. Nachdem Prinz {link:arthas-menethil}Arthas Menethil{/link} seinen Vater erschlagen und die {link:capital-city}Hauptstadt{/link} geplündert hatte, wollte er den Norden von ihren Ruinen aus beherrschen, und er ließ die {link:scourge}Geißel{/link} die Grüfte unter der Stadt vertiefen. Dann rief der Lichkönig ihn nach Nordend, und die Arbeit blieb unvollendet. Als der Griff des Lichkönigs schwächer wurde, befreite sich {link:sylvanas-windrunner}Sylvanas{/link}. Mit dem Schreckenslord {link:varimathras}Varimathras{/link}, den sie in ihren Dienst gezwungen hatte, stürzte sie die Dämonen, die das zerstörte Königreich beherrschen wollten, und sie nahm die gefallene Hauptstadt für ihr Volk in Besitz.

Die Verlassenen gingen unter die Erde. Sie sammelten die Toten mit freiem Willen aus den Ruinen darüber und brachten sie hinab, damit sie sich ihren Reihen anschlossen. Ein Steinmetz namens Bernd, aus den Ruinen gerettet, führte die Arbeiter an, die die neuen Hallen formten. Goblinhändler folgten und eröffneten die ersten Läden des Handelsviertels. Die Toten Lordaerons hatten wieder ein Zuhause.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Undercity ist vollendet, oder beinahe, und es ist voll. Vom {link:royal-quarter}Königsviertel{/link} aus führt {link:sylvanas-windrunner}Sylvanas{/link} Krieg gegen die {link:scourge}Geißel{/link} und gegen den {link:scarlet-crusade}Scharlachroten Kreuzzug{/link}. {link:varimathras}Varimathras{/link} befehligt die Verteidigung der Stadt. Im {link:the-apothecarium}Apothekarium{/link} arbeitet die {link:royal-apothecary-society}Königliche Apothekervereinigung{/link} an einer neuen Seuche, die die Dunkle Fürstin befohlen hat. Die Stadt hat sich der {link:horde}Horde{/link} angeschlossen und empfängt deren {link:orcs}Orcs{/link}, {link:trolls}Trolle{/link} und {link:tauren}Tauren{/link}, die sie beunruhigend finden. Ihr Volk erinnert sich auch an einen jüngsten Schrecken. Vor Kurzem zog die Nekropole {red:naxxramas}Naxxramas{/red} gegen die Stadt, und die Verlassenen bekämpften sie an der Oberfläche der Ruinen. Viele fielen dort, unter ihnen der Hauptmann der Todeswache.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Verlassenen.{/b} Bürger, Soldaten und Gelehrte des toten Königreichs, viele von ihnen einst Bewohner der {link:capital-city}Hauptstadt{/link} Lordaerons selbst.
• {b}Die {link:royal-apothecary-society}Königliche Apothekervereinigung{/link}.{/b} Die Chemiker des Apothekariums, mit ihren Gefangenen und ihren Monstrositäten.
• {b}Die Todeswache und die Königliche Schreckenswache.{/b} Die Soldaten der Stadt und die Wachen des Throns.
• {b}Goblins.{/b} Händler und Barbiere, die kamen, als die Stadt jung war, und denen es seither sehr gut ergangen ist.
• {b}Die Dunklen Waldläuferinnen.{/b} Untote Elfen, die der Dunklen Fürstin dienen und sich an {link:quel-thalas}Quel'Thalas{/link} erinnern.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die {link:capital-city}Hauptstadt{/link}.{/b} Jahrhundertelang herrschten die Könige von {link:lordaeron}Lordaeron{/link} vom Palast darüber.
• {b}Der Fall.{/b} Im {link:third-war}Dritten Krieg{/link} ermordete {link:arthas-menethil}Arthas{/link} König {link:terenas-menethil}Terenas Menethil{/link} und überließ die Stadt der {link:scourge}Geißel{/link}. Das war der {link:fall-of-lordaeron}Fall Lordaerons{/link}.
• {b}Die Tunnel.{/b} Die Geißel begann, Katakomben unter der Stadt zu graben, und ließ sie unvollendet.
• {b}Die Gründung.{/b} {link:sylvanas-windrunner}Sylvanas{/link} und ihre Verlassenen nahmen die Ruinen in Besitz und erbauten darunter ihre Stadt.
• {b}Der scharlachrote Angriff.{/b} Etwa ein Jahr nach der Gründung drang der Scharlachrote Kreuzzug durch seine Mauern in Undercity ein, und die Todeswache trieb ihn hinaus.
• {b}Die Nekropole.{/b} Als Naxxramas zuschlug, bekämpften die Verlassenen und die {link:argent-dawn}Argentumdämmerung{/link} sie gemeinsam über der Stadt.]=],
		},
		{
			title = "Überlieferungen der Stadt",
			text = [=[• Die Verlassenen sagen, der Goblin {link:glix-xizzix}Glix Xizzix{/link} habe die Hungernden der Stadt ernährt und ihre Verteidiger im Krieg gegen die {link:scourge}Geißel{/link} bewaffnet. Glix ist derjenige, der es am häufigsten sagt.
• Nahe dem Thron der Dunklen Fürstin ist manchmal ein Klagelied der {link:high-elves}Hochelfen{/link} zu hören. Es ist ein Lied von der gefallenen Heimat, die sie einst verteidigte.]=],
		},
	},
})

Translate("deDE", "trade-quarter", {
	title = "Handelsviertel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Handelsviertel ist das Herz von {link:undercity}Undercity{/link}, ein großer Ring aus Hallen am Fuß der Aufzüge, die von den Ruinen darüber herabführen. Hier stehen die Bank, das Auktionshaus, das Gasthaus und die Stände von hundert Händlern. Der Königliche Aufseher führt hier die Zählung der Stadt. Ein Goblin schneidet den Toten das Haar. Bettler warten in den Ecken auf Reste, und Apotheker eilen im Auftrag der Dunklen Fürstin an ihnen vorbei. Jeder Besucher von Undercity durchquert zuerst das Handelsviertel.]=],
		},
	},
})

Translate("deDE", "the-apothecarium", {
	title = "Das Apothekarium",
	aliases = { "Apothekarium" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Apothekarium ist das Reich der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link}. Ihre Chemiker nennen es das lebenswichtigste Organ von {link:undercity}Undercity{/link}. Jenseits eines Kanals aus grünem Schleim, in Gewölben voller brodelnder Bottiche und eingesperrter Gefangener, erforschen sie die Gifte aller Länder und brauen die neue Seuche, die {link:sylvanas-windrunner}die Dunkle Fürstin{/link} verlangt hat. {link:master-apothecary-faranell}Meisterapotheker Faranell{/link} herrscht hier. Seine Gehilfen nähen Monstrositäten aus allen Leichen zusammen, die sich finden lassen, und einer von ihnen verwandelt Gefangene in Bestien. Die Alchemisten der Stadt lehren in diesen Hallen auch ihr Handwerk, und Tränke, die eine lange Reise nicht überstehen, werden im Laufschritt hierhergebracht.]=],
		},
	},
})

Translate("deDE", "magic-quarter", {
	title = "Magieviertel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Magieviertel ist die Halle der Magier und Hexenmeister von {link:undercity}Undercity{/link}. Manche von ihnen studierten vor der Seuche das Arkane in {link:dalaran}Dalaran{/link} und verloren im Tod nichts von ihrer Gelehrsamkeit. Der mächtigste von ihnen ist der Magier {link:bethor-iceshard}Bethor Iceshard{/link}. Hier sind auch die Portalmeister der Stadt und eine Banshee, die die Künste des Magiers lehrt. Die Verlassenen dieses Viertels sind schlau und geduldig, und sie suchen jeden Gelehrten auf, der sich vom Lichkönig befreit hat.]=],
		},
	},
})

Translate("deDE", "war-quarter", {
	title = "Kriegsviertel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Kriegsviertel liegt im Nordwesten von {link:undercity}Undercity{/link}. Es ist der Stützpunkt des Militärs der Verlassenen und die Heimat der Priester der Stadt, die nun dem Schatten dienen. Hier bildet Undercity seine Kämpfer aus. Seine Hallen hallen vom Klirren der Übungsklingen und den Hämmern der Schmiede wider. Krieger erlernen hier ihr Handwerk, ein Waffenmeister lehrt jede Art von Waffen, und die Schmiede der Stadt arbeiten an ihren Essen. In diesen Tagen findet man in seinen Hallen sogar einen Lehrer der Paladine, ein Anblick, den viele {link:forsaken}Verlassene{/link} einst für unmöglich gehalten hätten.]=],
		},
	},
})

Translate("deDE", "royal-quarter", {
	title = "Königsviertel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Königsviertel liegt im tiefsten Teil von {link:undercity}Undercity{/link}, unter dem zerstörten Thronsaal, in dem {link:arthas-menethil}Arthas{/link} seinen Vater ermordete. Hier hält {link:sylvanas-windrunner}Sylvanas Windrunner{/link} Hof. Ihre Schreckenswachen säumen die Kammer, und {link:varimathras}Varimathras{/link} steht an ihrer Seite. Ihre Champions kommen hierher, um ihre Befehle zu empfangen, und hier sammeln die Hauptmänner der {link:horde}Horde{/link} Kämpfer für die fernen Schlachtfelder von {link:alterac-mountains}Alterac{/link}, {link:arathi-highlands}Arathi{/link} und {link:ashenvale}Eschental{/link}. Auch die Banshee Sharlindra schwebt durch die Kammer. Der verlassene Paladin {link:morbin-lightbane}Morbin Lightbane{/link} wartet in der Nähe und sammelt, was sein Volk braucht, um seine Toten wieder herzurichten.]=],
		},
	},
})

Translate("deDE", "sylvanas-windrunner", {
	title = "Sylvanas Windrunner",
	subtitle = "Die Bansheekönigin",
	found = "Das Königsviertel von Undercity",
	hint = [=[Sucht die Königin der Verlassenen in der tiefsten Halle von Undercity.]=],
	allegiance = "Verlassene · Horde · einst die Weitschreiter von Quel'Thalas",
	aliases = { "Sylvanas", "Lady Sylvanas Windrunner", "Lady Sylvanas", "die Dunkle Fürstin", "die Bansheekönigin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sylvanas Windrunner ist die Königin der {link:forsaken}Verlassenen{/link}. Zu Lebzeiten war sie die Waldläufergeneralin von {link:quel-thalas}Quel'Thalas{/link}, die Befehlshaberin seiner Waldläufer. Sie starb bei der Verteidigung ihrer Heimat gegen die {link:scourge}Geißel{/link}, und {link:arthas-menethil}Arthas{/link} erweckte sie als Banshee, damit sie ihm diene. Sie befreite sich, und sie führte die Untoten Lordaerons aus dem Griff des Lichkönigs. Ihr Volk nennt sie die Dunkle Fürstin. Es gehorcht ihr, und viele lieben sie.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Niemand tat mehr, um den Toten Lordaerons eine Zukunft zu geben. Sylvanas machte sie zu einem Volk, gab ihnen einen Namen und eine Stadt und führte sie in die {link:horde}Horde{/link}. Sie hat sie auch gefürchtet gemacht. Ihr Krieg gegen {link:arthas-menethil}Arthas{/link} ist persönlich. Ihr Krieg gegen die Lebenden ist schwerer zu erklären, und sie versucht nicht, ihn zu erklären.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie führte die Waldläufer von {link:quel-thalas}Quel'Thalas{/link} im {link:third-war}Dritten Krieg{/link} gegen die {link:scourge}Geißel{/link} und fiel vor {link:arthas-menethil}Arthas Menethil{/link}.
• Sie gewann ihren Willen zurück, als die Macht des Lichkönigs wankte.
• Sie zwang den Schreckenslord {link:varimathras}Varimathras{/link} in ihren Dienst und stürzte die Dämonen, die das zerstörte Königreich beherrschten.
• Sie nahm die Ruinen der {link:capital-city}Hauptstadt{/link} in Besitz und erbaute darunter {link:undercity}Undercity{/link}.
• Sie suchte Verbündete in der Ferne, und die Verlassenen schlossen sich der {link:horde}Horde{/link} an.
• Sie befahl der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link}, eine neue Seuche zu brauen, tödlicher als jede auf {link:azeroth}Azeroth{/link}, um die Geißel zu vernichten.]=],
		},
	},
	chapters = {
		{
			title = "Die Gründung",
			hint = [=[Erfahrt, wie die Toten Lordaerons unter den Ruinen ein Zuhause fanden.]=],
			text = [=[Als die Verlassenen zum ersten Mal unter die zerstörte {link:capital-city}Hauptstadt{/link} hinabstiegen, waren sie nur wenige. Sylvanas schickte ihre Diener in die Ruinen, um die Toten zu finden, die erwacht waren, und sie hinabzubringen, damit sie sich ihrem Volk anschlossen. Sie gab jedem von ihnen einen Platz und eine Pflicht. Wer ihr Treue schwor, war nie wieder allein.]=],
		},
		{
			title = "Eine neue Seuche",
			hint = [=[Helft den Apothekern von Brill beim Werk der Dunklen Fürstin.]=],
			text = [=[Sylvanas glaubt, dass die Künste der Apotheker, verbunden mit der neuen Magie der Verlassenen, den Schlüssel zum Untergang von {link:arthas-menethil}Arthas{/link} bergen. Sie hat ihre Chemiker herausgefordert, eine Seuche zu brauen, die sein Heer vernichten wird. Was diese Seuche sonst noch vernichten könnte, hat sie nicht gesagt.]=],
		},
		{
			title = "Die Paladine von Tyr's Watch",
			hint = "Bringt den Kopf eines Verräters zur Dunklen Fürstin.",
			text = [=[Die Verlassenen erinnern sich an das Licht als die Waffe, die die Lebenden gegen sie wandten. Als {link:danitha-morr}Danitha Morr{/link} ihr den Kopf eines befleckten Paladins schickte, der {link:forsaken}Verlassene{/link} ermordet hatte, nahm Sylvanas ihn ohne Wärme entgegen. Sie zweifle nicht an Danithas gutem Willen, sagte sie. Sie erwarte nur weiteren solchen Wahnsinn, und sie warnte den Orden, dass sie eines Tages beschließen könnte, er sei es nicht wert, erhalten zu werden.]=],
		},
		{
			title = "Ihr Champion",
			hint = "Beweist der Bansheekönigin Euren Wert.",
			text = [=[Unter den ersten Champions von Sylvanas war der Waldläufer {link:nathanos-blightcaller}Nathanos{/link}, heute der Seuchenrufer genannt. Er lebt allein in {link:the-marris-stead}Marris' Siedlung{/link} in den {link:eastern-plaguelands}Östlichen Pestländern{/link} und jagt dort die {link:scourge}Geißel{/link} und die {link:alliance}Allianz{/link}. Sylvanas schickt nur ihre abgehärtetsten Diener zu ihm.]=],
		},
	},
	mentions = {
		{ text = "Ein böses Erwachen" },
		{ text = "Eine neue Seuche" },
		{ text = "Ein Zeichen guten Willens" },
		{ text = "Der Champion der Bansheekönigin" },
	},
	bonds = {
		{ id = "varimathras", name = "Varimathras", note = "ihr gebundener Diener" },
		{ id = "arthas-menethil", name = "Arthas Menethil", note = "ihr Mörder" },
		{ id = "dark-ranger-anya", name = "Dunkle Waldläuferin Anya", note = "eine treue Waldläuferin" },
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "schwor ihr Treue" },
		{ id = "master-apothecary-faranell", name = "Meisterapotheker Faranell", note = "braut ihre Seuche" },
		{ id = "danitha-morr", name = "Danitha Morr", note = "führt einen Orden, dem sie misstraut" },
	},
})

Translate("deDE", "varimathras", {
	title = "Varimathras",
	subtitle = "Statthalter der Dunklen Fürstin",
	found = [=[Das Königsviertel von Undercity, an der Seite der Dunklen Fürstin]=],
	hint = [=[Sprecht mit dem Schreckenslord, der an der Seite der Bansheekönigin steht.]=],
	allegiance = "Verlassene · einst die Brennende Legion",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Varimathras ist ein Schreckenslord, einer der Nathrezim der {link:burning-legion}Brennenden Legion{/link}. Nach dem Fall von {link:archimonde}Archimonde{/link} versuchten er und seine Artgenossen, das zerstörte Königreich {link:lordaeron}Lordaeron{/link} für sich selbst an sich zu reißen. {link:sylvanas-windrunner}Sylvanas Windrunner{/link} nahm ihn gefangen und stellte ihn vor die Wahl: ihr dienen oder sterben. Er wählte den Dienst. Er half ihr, seine eigenen Brüder zu stürzen, und seither steht er an ihrer Seite, in der tiefsten Halle ihrer Stadt.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Varimathras ist der Statthalter der Dunklen Fürstin und der Herr über die Verteidigung von {link:undercity}Undercity{/link}. Seine Agenten und Soldaten streifen durch ganz {link:tirisfal-glades}Tirisfal{/link}, und er kümmert sich um die Feinde nahe der Heimat, während seine Königin den Norden im Auge behält. Dass ein Dämon der Legion den Verlassenen dient, ist eine seltsame Tatsache. Viele der Verlassenen ziehen es vor, nicht darüber nachzudenken. Wer darüber nachdenkt, weiß nur, was er gesehen hat: dass er seiner Königin seit dem Tag, an dem sie ihn verschonte, ohne Fehl gedient hat und dass er die Menschheit ebenso verachtet wie sie. Seinen Soldaten wird gesagt, dass er selbst dafür sorgt, dass das Menschengeschlecht aus {link:lordaeron}Lordaeron{/link} getilgt wird.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schwor {link:sylvanas-windrunner}Sylvanas{/link} die Treue und half ihr, die Schreckenslords zu stürzen, die das zerstörte Königreich beherrschten.
• Er befehligt die Verteidigung von {link:undercity}Undercity{/link}.
• Er lenkt den Krieg gegen den {link:scarlet-crusade}Scharlachroten Kreuzzug{/link} und will dessen Anführer tot sehen.
• Er empfängt die Berichte der Todespirscher, der Spione der Dunklen Fürstin.
• Er jagt die Agenten der {link:scourge}Geißel{/link} weit über {link:lordaeron}Lordaeron{/link} hinaus.
• Er sucht die Zauberbücher der Searing Blade, verborgen in den Höhlen unter {link:orgrimmar}Orgrimmar{/link}, für den Gebrauch der Dunklen Fürstin.]=],
		},
	},
	chapters = {
		{
			title = "Die roten Ameisen",
			hint = "Schlagt gegen das Herz des Scharlachroten Kreuzzugs zu.",
			text = [=[Während sich {link:sylvanas-windrunner}die Dunkle Fürstin{/link} um den Vormarsch des Lichkönigs im Norden kümmert, sieht Varimathras nach den Dingen nahe der Heimat. Er nennt den Scharlachroten Kreuzzug den schärfsten {link:dorn-plainstalker}Dorn{/link} im Fleisch der Verlassenen, und er will die {link:high-inquisitor-whitemane}Hochinquisitorin Whitemane{/link} und ihre wichtigsten Statthalter in den Hallen des {link:scarlet-monastery}Scharlachroten Klosters{/link} erschlagen sehen.]=],
		},
		{
			title = "Die Todespirscher",
			hint = "Deckt die Ränke der Lords von Alterac auf.",
			text = [=[Die Todespirscher erfuhren, dass das {link:syndicate}Syndikat{/link} aus den alten Lords von {link:alterac-mountains}Alterac{/link} bestand, den Verrätern des {link:second-war}Zweiten Krieges{/link}. Ihr Bericht gelangte zu Varimathras. Er ist mit solcher Arbeit zufrieden, und er belohnt sie.]=],
		},
		{
			title = "Ein unheiliges Bündnis",
			hint = [=[Findet den Gesandten der Geißel, der zu den Stacheleberen geschickt wurde.]=],
			text = [=[Der Lichkönig schickte einen Gesandten namens {link:ambassador-malcin}Malcin{/link} zu den Stacheleberen in den Hügeln von Razorfen, und einige der Stachelebere begannen, die Zeichen der Seuche zu zeigen. Varimathras wollte den Gesandten tot und seine Mission gescheitert sehen. Als Malcin fiel, ließ der Schreckenslord den Dank der Dunklen Fürstin übermitteln.]=],
		},
	},
	mentions = {
		{ text = "Ins Scharlachrote Kloster" },
		{ text = "Die Todespirscher" },
		{ text = "Ein unheiliges Bündnis" },
		{ text = "Die Macht zu zerstören..." },
		{ text = "Beweis des Ablebens" },
	},
	bonds = {
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "seine Königin" },
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "stellte auf seinen Befehl die Stadtwache auf" },
	},
})

Translate("deDE", "master-apothecary-faranell", {
	title = "Meisterapotheker Faranell",
	subtitle = "Herr des Apothekariums",
	found = "Das Apothekarium",
	hint = [=[Sucht den Meisterapotheker in den Gewölben des Apothekariums.]=],
	allegiance = "Königliche Apothekervereinigung",
	aliases = { "Faranell" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Meisterapotheker Faranell herrscht über das {link:the-apothecarium}Apothekarium{/link}. Er überwacht das ehrgeizigste Werk der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link}: die neue Seuche, die {link:sylvanas-windrunner}die Dunkle Fürstin{/link} befohlen hat, eine Krankheit, die der {link:scourge}Geißel{/link} und mit der Zeit auch den Lebenden den Untergang bringen soll. Seine Kollegen schicken ihm ihre Ergebnisse aus dem {link:silverpine-forest}Silberwald{/link}, aus {link:hillsbrad-foothills}Hillsbrad{/link} und von weiter her. Er ist auf eine Weise vergnügt bei seiner Arbeit, die jene erschreckt, die sie verstehen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Bei Faranell fließt das Wissen der Vereinigung zusammen. Er erschafft auch Monstrositäten für {link:sylvanas-windrunner}die Dunkle Fürstin{/link}, und er ist sich für einen Scherz auf Kosten seiner Versuchsobjekte nicht zu schade.]=],
		},
		{
			title = "Taten",
