	aliases = { "Morbin" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Morbin Lightbane ist ein verlassener Paladin. Er glaubt, dass seine Pflicht zweifach ist: den Willen der Dunklen Fürstin auszuführen und für die Bedürfnisse seines Volkes zu sorgen. Über {link:undercity}Undercity{/link} streift die {link:scourge}Geißel{/link} noch immer in großer Zahl durch die Ruinen, und die Verlassenen, die gegen sie kämpfen, fallen. Verwesendes Fleisch heilt nicht von selbst. Morbin sammelt unversehrte Gliedmaßen von den gefallenen Toten, damit seine Brüder und Schwestern wieder hergerichtet werden können.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Morbin hält die Erinnerung an {link:garek-bandarion}Garek Bandarion{/link} lebendig, den er den glorreichen Hauptmann nennt. Er glaubt, Garek hätte gewollt, dass die Ruinen zurückerobert und seine Verwandten geheilt werden. Wer Morbin bringt, was er braucht, sagt er, macht seinem Hauptmann Ehre.]=],
		},
	},
	mentions = {
		{ text = "Die Gerechtigkeit des Lichts" },
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "der Hauptmann, den er ehrt" },
	},
})
